INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-s2','official-en-school-scenario','scenario_decision','Bạn đến trường nhưng không tìm thấy phòng học mới. Nên làm gì trước?','["Kiểm tra thông báo và hỏi đầu mối phụ trách","Tự chọn một phòng bất kỳ","Về nhà ngay","Đợi mà không báo ai"]','["Kiểm tra thông báo và hỏi đầu mối phụ trách"]','[]','','','','','','','',0,1,'','',3,'["school-workplace","scenario"]',1,'2026-09-11','2026-09-11');
