INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-s4','official-en-school-scenario','ordering','Sắp xếp quy trình chuẩn bị một buổi học.','["Xác nhận phòng","Chuẩn bị nội dung","Kiểm tra thiết bị","Đón học viên","Tổng kết"]','["Xác nhận phòng Chuẩn bị nội dung Kiểm tra thiết bị Đón học viên Tổng kết"]','[]','','','','','','','',0,1,'','',4,'["school","workflow"]',3,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-s5','official-en-school-scenario','error_correction','Chọn thông báo phù hợp nhất khi phải đổi lịch đột xuất.','["Xin lỗi vì thay đổi đột xuất. Buổi học chuyển sang 20:00; vui lòng xác nhận bạn đã nhận thông tin.","Đổi giờ nha.","Tự xem lại đi.","Không cần thông báo."]','["Xin lỗi vì thay đổi đột xuất. Buổi học chuyển sang 20:00; vui lòng xác nhận bạn đã nhận thông tin."]','[]','','','','','','','',0,1,'','',4,'["school","formal"]',4,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-s6','official-en-school-scenario','reading_group','Từ thông báo, hành động nào cần làm trước buổi học?','["Kiểm tra địa điểm mới và đến sớm","Chỉ đến sau giờ học","Không đọc thông báo","Tự đổi sang ngày khác"]','["Kiểm tra địa điểm mới và đến sớm"]','[]','','','','','','','',0,1,'Ban tổ chức thông báo phòng học thay đổi. Học viên cần kiểm tra địa điểm mới, có mặt trước 10 phút và liên hệ đầu mối nếu gặp khó khăn.','',3,'["reading","school"]',5,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-s7','official-en-school-scenario','translation','Diễn đạt/nhận diện câu dùng để xác nhận phòng học: “Please confirm the room number.”','[]','["Please confirm the room number.","Vui lòng xác nhận số phòng học."]','[]','','','','','','','',0,1,'','',3,'["translation","school"]',6,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-s8','official-en-school-scenario','roleplay','Role-play: bạn là người phụ trách lớp và có học viên đến nhầm phòng. Phản hồi nào tốt nhất?','["Chào bạn, mình sẽ chỉ phòng mới và cập nhật lại thông tin để bạn không bị nhầm lần sau.","Bạn tự tìm đi.","Không phải việc của mình.","Im lặng."]','["Chào bạn, mình sẽ chỉ phòng mới và cập nhật lại thông tin để bạn không bị nhầm lần sau."]','[]','','','','','','','',0,1,'','',5,'["roleplay","school-workplace"]',7,'2026-09-11','2026-09-11');

INSERT OR REPLACE INTO question_sets(id,title,language,level,topic,context,skill,description,is_official,visibility,status,version,created_by,created_at,updated_at) VALUES ('official-en-travel-public','English — Travel & Public Services','en','Everyday / Intermediate','Travel & Public Services','Travel','Dialogue / Reading / Scenario','Sân bay, khách sạn, phương tiện, hỏi đường và dịch vụ công cộng.',1,'public','published',1,NULL,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-t1','official-en-travel-public','dialogue','Bạn cần hỏi đường tới ga gần nhất. Chọn câu phù hợp.','["Where is the nearest station?","I would like to make a reservation.","Please confirm the room number.","Could you repeat that, please?"]','["Where is the nearest station?"]','[]','','','','','','','',0,1,'','',2,'["travel","dialogue"]',0,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('en-t2','official-en-travel-public','dialogue','Bạn muốn đặt phòng khách sạn. Chọn câu phù hợp.','["I would like to make a reservation.","Could you repeat that, please?","Where is the nearest station?","Please confirm the room number."]','["I would like to make a reservation."]','[]','','','','','','','',0,1,'','',2,'["hotel","dialogue"]',1,'2026-09-11','2026-09-11');
