INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s5','official-ru-school-scenario','error_correction','Chọn thông báo phù hợp nhất khi phải đổi lịch đột xuất.','["Xin lỗi vì thay đổi đột xuất. Buổi học chuyển sang 20:00; vui lòng xác nhận bạn đã nhận thông tin.","Đổi giờ nha.","Tự xem lại đi.","Không cần thông báo."]','["Xin lỗi vì thay đổi đột xuất. Buổi học chuyển sang 20:00; vui lòng xác nhận bạn đã nhận thông tin."]','[]','','','','','','','',0,1,'','',4,'["school","formal"]',4,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s6','official-ru-school-scenario','reading_group','Từ thông báo, hành động nào cần làm trước buổi học?','["Kiểm tra địa điểm mới và đến sớm","Chỉ đến sau giờ học","Không đọc thông báo","Tự đổi sang ngày khác"]','["Kiểm tra địa điểm mới và đến sớm"]','[]','','','','','','','',0,1,'Ban tổ chức thông báo phòng học thay đổi. Học viên cần kiểm tra địa điểm mới, có mặt trước 10 phút và liên hệ đầu mối nếu gặp khó khăn.','',3,'["reading","school"]',5,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s7','official-ru-school-scenario','translation','Diễn đạt/nhận diện câu dùng để xác nhận phòng học: “Пожалуйста, подтвердите номер аудитории.”','[]','["Пожалуйста, подтвердите номер аудитории.","Vui lòng xác nhận số phòng học."]','[]','','','','','','','',0,1,'','',3,'["translation","school"]',6,'2026-09-11','2026-09-11');
INSERT OR REPLACE INTO questions(id,set_id,type,prompt,options_json,answers_json,pairs_json,explanation,hint,media_url,media_type,transcript,tts_text,tts_lang,max_plays,playback_rate,passage,context,difficulty,tags_json,sort_order,created_at,updated_at) VALUES ('ru-s8','official-ru-school-scenario','roleplay','Role-play: bạn là người phụ trách lớp và có học viên đến nhầm phòng. Phản hồi nào tốt nhất?','["Chào bạn, mình sẽ chỉ phòng mới và cập nhật lại thông tin để bạn không bị nhầm lần sau.","Bạn tự tìm đi.","Không phải việc của mình.","Im lặng."]','["Chào bạn, mình sẽ chỉ phòng mới và cập nhật lại thông tin để bạn không bị nhầm lần sau."]','[]','','','','','','','',0,1,'','',5,'["roleplay","school-workplace"]',7,'2026-09-11','2026-09-11');

